import clsx from 'clsx';
import React, { forwardRef, ReactNode } from 'react';
import { isElement } from 'react-is';

import {
  avatarAbbreviationCSS,
  avatarDisabledCSS,
  avatarWrapperCSS,
} from './Avatar.sty.js';
import { Label } from './Label.js';
import { Subtitle } from './Subtitle.js';
import { _useAriaLabelingProps } from '../../core/hooks/useAriaLabelingProps.js';
import { useFocusRing } from '../../core/styles/useFocusRing.js';
import type { AriaLabelingProps } from '../../core/types/a11y-props.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { _sanitizeSymbol } from '../../core/utils/sanitize-symbol.js';
import { Flex } from '../../layouts-core/flex/Flex.js';
import { textStyleCSS } from '../../styles/textStyle.sty.js';

// Merge own props with others inherited from the underlying element type
export type AvatarProps<E extends React.ElementType> =
  PolymorphicComponentProps<E, AvatarOwnProps>;

/** Accepted properties for the Avatar component */
export interface AvatarOwnProps
  extends WithChildren,
    AriaLabelingProps,
    StylingProps,
    DataTestId {
  /**
   * The size of the Avatar.
   * @defaultValue 'default'
   */
  size?: 'default' | 'small';

  /**
   * The letters displayed in the colored circle of the Avatar.
   */
  abbreviation: string;

  /**
   * Whether the Avatar is disabled.
   * @defaultValue false
   */
  disabled?: boolean;
}

type AvatarSlots = {
  label?: ReactNode;
  subtitle?: ReactNode;
};

/** Iterates over child nodes to extract specific component slots. */
function getAvatarSlots(children: React.ReactNode) {
  const slots: AvatarSlots = {};

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Label:
          slots.label = child;
          break;
        case Subtitle:
          slots.subtitle = child;
          break;
      }
    }
  });

  return slots;
}

/** Avatar component */
export const _Avatar: <E extends React.ElementType = 'div'>(
  props: AvatarProps<E>,
) => React.ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends React.ElementType>(
    props: AvatarProps<E>,
    ref: typeof props.ref,
  ) => {
    const {
      children,
      size = 'default',
      abbreviation,
      disabled = false,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      as,
      ...remainingProps
    }: AvatarProps<E> = props;
    const slots = getAvatarSlots(children);
    const ariaLabelingProps = _useAriaLabelingProps(remainingProps);

    const { focusProps, focusClassName } = useFocusRing();

    const Abbreviation = as ?? 'div';

    return (
      <div
        className={clsx(avatarWrapperCSS, textStyleCSS({ textStyle: 'base' }))}
      >
        <Flex gap={size === 'small' ? 4 : 8} alignItems="center">
          <Abbreviation
            ref={ref}
            data-testid={dataTestId}
            className={clsx(
              { [avatarDisabledCSS]: disabled },
              avatarAbbreviationCSS({ size, disabled }),
              textStyleCSS({ textStyle: size === 'small' ? 'small' : 'base' }),
              focusClassName,
              consumerClassName,
            )}
            style={consumerStyle}
            {...focusProps}
            {...ariaLabelingProps}
            {...remainingProps}
          >
            {_sanitizeSymbol(abbreviation, size === 'default' ? 2 : undefined)}
          </Abbreviation>
          {(slots.label || slots.subtitle) && (
            <Flex flexDirection="column" gap={0}>
              {slots.label}
              {slots.subtitle}
            </Flex>
          )}
        </Flex>
      </div>
    );
  },
);

(_Avatar as typeof _Avatar & { displayName: string }).displayName = 'Avatar';

/**
 * The `Avatar` component can be used as a visual representation of a user.
 */
export const Avatar = Object.assign(_Avatar, {
  Label,
  Subtitle,
});
